-- Ham nhat trung dung CollectionService chinh xac
local function CollectEgg()
    local char = plr.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChild("Humanoid")
    if not root or not hum or hum.Health <= 0 then return false end

    -- Tim Remote khong dung WaitForChild (tranh yield)
    local EggRemote = nil
    pcall(function()
        EggRemote = game:GetService("ReplicatedStorage").Modules.Net["RE/EasterServiceRE"]
    end)
    if not EggRemote then return false end

    local eggs = game:GetService("CollectionService"):GetTagged("EasterEgg26")
    if #eggs == 0 then return false end

    for _, egg in pairs(eggs) do
        local uid = egg:GetAttribute("UID")
        if uid and egg:IsA("BasePart") then
            -- BAM TRUNG 10 LAN - theo duoi Eggcited Egg
            for i = 1, 10 do
                if not egg or not egg.Parent then break end
                pcall(function()
                    root.CFrame = CFrame.new(egg.Position + Vector3.new(0, 2, 0))
                end)
                task.wait(0.1)
            end
            -- FIRE REMOTE 5 LAN
            for i = 1, 5 do
                pcall(function()
                    EggRemote:FireServer("CollectEgg", {UID=uid, Additional={}})
                end)
                task.wait(0.1)
            end
            return true
        end
    end
    return false
end

-- Bay muot den dao bang Tween2 (giong farm mob)
local function FlyToIsland(dest)
    _G.StopTween2 = false
    pcall(function() Tween2(dest * CFrame.new(0, 8, 0)) end)
end

