-- Limit FPS to 60 for smooth play
local targetFPS = 60
local lastTime = tick()
RunService.RenderStepped:Connect(function()
    local currentTime = tick()
    local delta = currentTime - lastTime
    
    if delta < 1/targetFPS then
        wait(1/targetFPS - delta)
    end
    
    lastTime = currentTime
end)

-- Reduce simulation radius (tránh load quá nhiều object)
