local RS = game:GetService("ReplicatedStorage")
local CS = game:GetService("CollectionService")
local Remote = RS:WaitForChild("Modules"):WaitForChild("Net"):WaitForChild("RE/EasterServiceRE")

local function CollectEgg()
    local char = plr.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChild("Humanoid")
    
    if not root or not hum or hum.Health <= 0 then return false end

    local Remote = RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("Net") and RS.Modules.Net:FindFirstChild("RE/EasterServiceRE")
    if not Remote then return false end

    local eggs = CS:GetTagged("EasterEgg26")
    for i = 1, #eggs do
        local egg = eggs[i]
        local uid = egg:GetAttribute("UID")
        local cf = egg:GetAttribute("CFrame")
        if uid and cf then
            pcall(function()
                _tp(cf + Vector3.new(0, 2, 0))
                Remote:FireServer("CollectEgg", {
                    UID = uid,
                    Additional = {}
                })
            end)
            return true
        end
    end
    return false
end

spawn(function()
    local currentIndex = 1
    local lastIslandTP = 0
    local isFlying = false -- KHOA LOOP KHI DANG BAY

    while wait(1) do
        if _G.AutoCollectEgg then
            -- NEU DANG BAY THI KHONG LAM GI HET - tranh doi huong
            if isFlying then continue end

            local char = plr.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChild("Humanoid")

            if root and hum and hum.Health > 0 then
                local hasEgg = CollectEgg()
                
                if not hasEgg then
                    if _G.ChooseEgg == "Chest" then
                        _G.AutoFarmChest = true
                    elseif _G.ChooseEgg == "Island" then
                        _G.AutoFarmChest = false
                        if #IslandPositions > 0 and (tick() - lastIslandTP) > 2 then
                            isFlying = true -- KHOA LOOP TRUOC KHI BAY
                            local dest = IslandPositions[currentIndex]
                            currentIndex = currentIndex + 1
                            if currentIndex > #IslandPositions then
                                currentIndex = 1
                            end
                            lastIslandTP = tick()
                            pcall(function()
                                _tp(dest)
                            end)
                            -- Cho bay xong theo khoang cach thuc te
                            local dist = 500
                            pcall(function()
                                if root then
                                    dist = (dest.Position - root.Position).Magnitude
                                end
                            end)
                            task.wait(math.clamp(dist / 300, 2, 15))
                            isFlying = false -- MO KHOA SAU KHI BAY XONG
                        end
                    elseif _G.ChooseEgg == "Normal" then
                        _G.AutoFarmChest = false
                    end
                else
                    _G.AutoFarmChest = false
                end
            else
                _G.AutoFarmChest = false
                task.wait(1)
            end
        else
            _G.AutoFarmChest = false
            currentIndex = 1
            isFlying = false
        end
    end
end)

