_G.BringMob = true

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local function GetRandomEnemies(amount)
    local enemies = game:GetService("Workspace").Enemies:GetChildren()
    local validEnemies = {}
    
    for _, mob in ipairs(enemies) do
        if mob:FindFirstChild("Humanoid") and mob.Humanoid.Health > 0 and mob:FindFirstChild("HumanoidRootPart") then
            if mob.Name ~= "Factory Staff" and (not MonFarm or mob.Name == MonFarm) then
                table.insert(validEnemies, mob)
            end
        end
    end
    
    for i = #validEnemies, 2, -1 do
        local j = math.random(1, i)
        validEnemies[i], validEnemies[j] = validEnemies[j], validEnemies[i]
    end
    
    local result = {}
    for i = 1, math.min(amount, #validEnemies) do
        table.insert(result, validEnemies[i])
    end
    
    return result
end

task.spawn(function()
    while task.wait() do 
        if not _G.BringMob then continue end
        
        pcall(function()
            local targets = GetRandomEnemies(4)
            
            local targetPos = typeof(FarmPos) == "CFrame" and FarmPos.Position or FarmPos.Position
            local targetCFrame = typeof(FarmPos) == "CFrame" and FarmPos or FarmPos.CFrame
            
            for _, mob in ipairs(targets) do
                local hrp = mob.HumanoidRootPart
                local hum = mob.Humanoid
                
                local dist = (hrp.Position - targetPos).Magnitude
                
                hrp.Size = Vector3.new(60, 60, 60)
                hrp.Transparency = 1
                hrp.CanCollide = false
                if mob:FindFirstChild("Head") then 
                    mob.Head.CanCollide = false 
                end
                
                hum.JumpPower = 0
                hum.WalkSpeed = 0
                if hum:FindFirstChild("Animator") then 
                    hum.Animator:Destroy() 
                end
                
                hum:ChangeState(11)
                hum:ChangeState(14)
                
                pcall(function() sethiddenproperty(LocalPlayer, "SimulationRadius", math.huge) end)

                if dist <= 50 then
                    hrp.CFrame = targetCFrame
                else
                    hrp.CFrame = CFrame.lookAt(hrp.Position, targetPos) * CFrame.new(0, 0, -15)
                end
            end
        end)
    end
end)
