spawn(function()
    local currentIndex = 1
    local lastIslandTP = 0
    local isFlying = false

    while wait(1) do
        if not _G.AutoCollectEgg then
            currentIndex = 1
            isFlying = false
            continue
        end
        if isFlying then continue end

        local char = plr.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChild("Humanoid")
        if not root or not hum or hum.Health <= 0 then task.wait(1) continue end

        local hasEgg = CollectEgg()

        if not hasEgg and _G.ChooseEgg == "Island" then
            if #IslandPositions > 0 and (tick() - lastIslandTP) > 2 then
                isFlying = true
                local dest = IslandPositions[currentIndex]
                currentIndex = currentIndex + 1
                if currentIndex > #IslandPositions then currentIndex = 1 end
                lastIslandTP = tick()
                Library:Notify({Title="Crazy Hub | Blox Fruit | Make By Kim Long Valencia", Content="🥚 Bay sang đảo "..currentIndex.."/"..#IslandPositions, Duration=2})
                FlyToIsland(dest)
                isFlying = false
            end
        end
    end
end)
