        SaveSettings()

        task.spawn(function()
            while _G.AcceptAlly do
                pcall(function()
                    local remote = game:GetService("ReplicatedStorage").Remotes.CommF_
                    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                        if p.Name ~= game.Players.LocalPlayer.Name then
